SELECT r.revision, r.namespace, r.id, r.client_id, r.request_id, r.profile_channel, r.browser_instance, r.trust_scope, r.old_broker_epoch, r.old_channel_epoch, r.old_scope_hash, r.process_evidence_json, r.policy_evidence_json, r.evidence_digest, r.phase, r.manifest_digest, r.manifest_count, r.receipt_count, r.adoption_evidence_json, r.adoption_digest, r.created_at, r.updated_at FROM (SELECT * FROM  (SELECT r.* FROM chrome_retirements r WHERE r.namespace=:Namespace AND r.client_id=:ClientID AND r.id=:TransitionID
)  records) r WHERE $criteria.CompositeIn("r", $WriteChromeRetirementKeys)